import logging
from taf.gnb.oam.ne3s.ws.components.base import FunctionalComponent
from taf.gnb.oam.ne3s.ws.components.PM.v1.resources.notifications.messages import (
    PmUploadNotification, PMNotificationGroup)


log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


class PmReportingNotActive(Exception):
    pass


class PMv1(FunctionalComponent):
    STREAMS = None
    _connection = None
    SUPPORTED_NOTIFICATIONS = PMNotificationGroup

    def __init__(self, connection):
        self._connection = connection
        self.STREAMS = []
        self._latest_report_stream = None

    @property
    def latest_report_stream(self):
        if self._latest_report_stream is not None:
            return self._latest_report_stream
        else:
            raise PmReportingNotActive('Please activate PM reporting first.')

    @latest_report_stream.setter
    def latest_report_stream(self, value):
        self._latest_report_stream = value

    def prepare_params_for_pm_measurement(self, collection_interval, reporting_interval):
        collection_entity_ip = self._connection.connection_details.netact_server_address
        collection_entity_port = self._connection.connection_details.netact_server_port
        pm_measurement_params = {'rTPmCollEntity': [{'rTPmCollEntityIpAddr': collection_entity_ip,
                                                     'rTPmCollEntityPortNum': collection_entity_port,
                                                     'rTPmCollInterval': collection_interval}],
                                 'reportingIntervalPm': reporting_interval}
        return pm_measurement_params

    def activate_pm_collection_stream(self, stream_size=1, stream_overwrite=True):
        self.latest_report_stream = self.add_new_msg_stream(
            stream_name="PM.latest_report",
            msg_list=[PmUploadNotification],
            size=stream_size,
            overwrite=stream_overwrite
        )

    def fetch_latest_report(self, timeout):
        pm_notification_content = self.latest_report_stream.get(timeout=timeout).attachment.content
        return pm_notification_content
